import { useEffect, useMemo, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { RefreshCw, ShieldAlert, TrendingDown, TrendingUp } from 'lucide-react';
import { api } from '../lib/api';
import BasemapPicker from './BasemapPicker';
import { useLeafletPanelMap } from '../lib/useLeafletPanelMap';
import type { EquityReport, EquityStop, WardDemographicsResponse } from '../types';
import { fmtMin, fmtInt } from '../lib/format';
import { PanelSkeleton } from './PanelStates';
import SourceNote from './SourceNote';
import NewHereHint from './NewHereHint';

/**
 * Councillor equity view: who wins and who loses, mapped.
 *
 * Renders the offline-generated `docs/equity-report.json` (served by
 * `GET /api/equity/report`): a map with every transfer stop colored by its
 * net wait change (green = better, red = worse), plus the winners / losers /
 * ward tables so a council discussion can weigh the concentrated wins against
 * the concentrated losses instead of arguing about averages.
 */

const WIN_COLOR = '#16a34a';
const LOSE_COLOR = '#dc2626';
const NEUTRAL_COLOR = '#94a3b8';

function fmt(mins: number): string {
  const sign = mins > 0 ? '+' : '';
  return `${sign}${fmtMin(mins)}`;
}

function stopRadius(stop: EquityStop): number {
  // Radius scales with the absolute impact (minutes), clamped so a single
  // huge stop doesn't swamp the map.
  return 6 + Math.min(14, Math.abs(stop.delta_minutes) * 2);
}

export default function EquityPanel() {
  const [data, setData] = useState<EquityReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<EquityStop | null>(null);
  const [wardDemo, setWardDemo] = useState<WardDemographicsResponse | null>(null);
  // Shared panel-map bootstrap: deferred-mount creation, ResizeObserver,
  // basemap sync, and the mapReady-keyed tile effect (see the hook docstring
  // for why each invariant exists).
  const {
    ref: mapRefCb,
    mapRef: leafletRef,
    layerRef,
  } = useLeafletPanelMap();

  const load = useMemo(
    () => async () => {
      setLoading(true);
      setError(null);
      try {
        // Try the on-the-fly compute endpoint first (uses latest optimizer run).
        // Falls back to the file-based report if no optimization has been run.
        let d: EquityReport;
        try {
          d = await api.equityCompute();
        } catch {
          d = await api.equityReport();
        }
        setData(d);
        // Also fetch ward demographics (non-blocking)
        api.wardDemographics().then(setWardDemo).catch(() => {});
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
        setData(null);
      } finally {
        setLoading(false);
      }
    },
    []
  );

  useEffect(() => {
    void load();
  }, [load]);

  // Draw markers whenever the report (or selection) changes.
  useEffect(() => {
    const map = leafletRef.current;
    const layer = layerRef.current;
    if (!map || !layer || !data) return;

    layer.clearLayers();
    const stops = [...(data.winners ?? []), ...(data.losers ?? [])];
    const pts: L.LatLng[] = [];

    for (const s of stops) {
      if (s.lat == null || s.lon == null) continue;
      const pt = L.latLng(s.lat, s.lon);
      pts.push(pt);
      const win = s.delta_minutes < 0;
      const color = win ? WIN_COLOR : s.delta_minutes > 0 ? LOSE_COLOR : NEUTRAL_COLOR;
      const marker = L.circleMarker(pt, {
        radius: stopRadius(s),
        color: '#ffffff',
        weight: 1,
        fillColor: color,
        fillOpacity: s.stop_id === selected?.stop_id ? 0.95 : 0.65,
      });
      const riders =
        s.riders_at_stop_proxy > 0
          ? `${s.riders_at_stop_proxy.toLocaleString()} riders at stop`
          : 'no boarding data';
      marker.bindPopup(
        `<b>${s.stop_name}</b><br/>Routes ${s.routes.join(', ')}<br/>` +
          `<b>${fmt(s.delta_minutes)}</b> avg wait change<br/>` +
          `${s.worse_off_connections} worse-off connections` +
          (s.worse_off_max_minutes > 0
            ? ` (worst ${fmt(s.worse_off_max_minutes)})`
            : '') +
          `<br/>${riders}`
      );
      marker.on('click', () => setSelected(s));
      layer.addLayer(marker);
    }

    if (pts.length > 0) {
      map.fitBounds(L.latLngBounds(pts).pad(0.15));
    } else {
      map.setView([43.589, -79.6441], 11);
    }
  }, [data, selected]);

  const stopRows = (stops: EquityStop[]) =>
    stops.map((s) => (
      <tr
        key={s.stop_id}
        className={`cursor-pointer border-b border-border/60 ${
          selected?.stop_id === s.stop_id ? 'bg-accent/10' : 'hover:bg-card-hover'
        }`}
        onClick={() => setSelected(s)}
      >
        <td className="px-2 py-1.5 text-xs font-semibold text-text-primary">{s.stop_name}</td>
        <td className="px-2 py-1.5 text-xs text-text-secondary">{s.routes.join(', ')}</td>
        <td
          className={`px-2 py-1.5 text-right text-xs font-bold ${
            s.delta_minutes < 0 ? 'text-optimized' : 'text-danger'
          }`}
        >
          {fmt(s.delta_minutes)}
        </td>
        <td className="px-2 py-1.5 text-right text-xs text-text-secondary">
          {s.worse_off_connections > 0 ? s.worse_off_connections : '—'}
        </td>
        <td className="px-2 py-1.5 text-right text-xs text-text-muted">
          {s.riders_at_stop_proxy > 0 ? fmtInt(s.riders_at_stop_proxy) : '—'}
        </td>
      </tr>
    ));

  return (
    <div className="flex flex-1 flex-col gap-3 overflow-hidden">
      <div className="relative overflow-hidden rounded-xl border border-border bg-card px-4 py-3">
        <div className="absolute inset-x-0 top-0 h-0.5 edge-gradient-blue" />
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-sm font-bold text-text-primary">Equity: who wins, who loses</h2>
            {data && (
              <p className="mt-0.5 text-xs text-text-muted">
                {data.period} · {data.volume_mode} weighting · {data.solver_status} ·{' '}
                {data.total_connections.toLocaleString()} connections ·{' '}
                <span className="text-optimized">
                  {data.passenger_minutes_saved.toLocaleString()} passenger-min saved
                </span>
                {data.solver_variance_pct != null && (
                  <span className="ml-2 rounded-full border border-amber-500/40 bg-amber-500/10 px-1.5 py-0.5 text-[10px] font-semibold normal-case text-amber-400"
                    title="FEASIBLE solves are non-deterministic. Across identical-config runs, network passenger-minutes saved varies ±1% (ward/stop level varies more). This is the estimated run-to-run spread.">
                    run variance ±{data.solver_variance_pct}%
                  </span>
                )}
              </p>
            )}
          </div>
          <button
            onClick={() => void load()}
            className="flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-semibold text-text-secondary transition-colors hover:bg-card-hover"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Reload
          </button>
        </div>
      </div>

      <NewHereHint text="Green stops see shorter waits after the change; red stops see longer waits. This view helps weigh whether the benefits are spread fairly across the city." />

      {error ? (
        <div className="flex flex-1 items-center justify-center rounded-xl border border-border bg-card p-8">
          <div className="max-w-md text-center">
            <ShieldAlert className="mx-auto mb-3 h-8 w-8 text-bottleneck" />
            <p className="text-sm font-semibold text-text-primary">No equity report available</p>
            <p className="mt-2 text-xs leading-relaxed text-text-secondary">
              {error}. The report is generated from the backend directory with{' '}
              <code className="rounded bg-card-hover px-1 py-0.5 text-[10px]">
                python scripts/equity_report.py --period late_night --ward-csv app/data/ward_stops.csv
              </code>
              {' '}— if that's not you, ask whoever runs the tool to regenerate it.
            </p>
          </div>
        </div>
      ) : !data ? (
        loading ? (
          <div className="flex flex-1 flex-col gap-3">
            <PanelSkeleton label="Loading equity report…" />
          </div>
        ) : (
          <div className="flex flex-1 items-center justify-center rounded-xl border border-border bg-card p-8">
            <div className="max-w-md text-center">
              <ShieldAlert className="mx-auto mb-3 h-8 w-8 text-bottleneck" />
              <p className="text-sm font-semibold text-text-primary">No optimization results yet</p>
              <p className="mt-2 text-xs leading-relaxed text-text-secondary">
                The equity view is computed from the latest optimization run. Run the optimizer on the Fix transfers tab first — once it completes, come back here and the winners/losers will appear automatically.
              </p>
              <div className="mt-4 rounded-lg border border-border bg-bg p-3 text-left">
                <p className="text-[10px] font-bold uppercase tracking-wider text-text-muted">How it works</p>
                <ol className="mt-2 space-y-1.5 text-[11px] text-text-secondary">
                  <li><span className="font-semibold text-text-primary">1.</span> Go to <span className="font-semibold text-optimized">Fix transfers</span> and run an optimization</li>
                  <li><span className="font-semibold text-text-primary">2.</span> Come back here — equity is computed automatically from the result</li>
                </ol>
              </div>
            </div>
          </div>
        )
      ) : (
        <div className="flex flex-1 flex-col gap-3 overflow-y-auto">
          <div className="relative">
            <div ref={mapRefCb} className="h-72 w-full shrink-0 rounded-xl border border-border" />
            <BasemapPicker className="absolute right-2 top-2 rounded-md bg-white/95" />
          </div>

          {/* legend */}
          <div className="flex items-center gap-4 px-1 text-xs text-text-secondary">
            <span className="flex items-center gap-1.5">
              <span className="h-2.5 w-2.5 rounded-full bg-[#16a34a]" /> wait reduced
            </span>
            <span className="flex items-center gap-1.5">
              <span className="h-2.5 w-2.5 rounded-full bg-[#dc2626]" /> wait increased
            </span>
            <span className="ml-auto text-text-muted">
              {data.winners?.length ?? 0} winning · {data.losers?.length ?? 0} worse-off stops
            </span>
          </div>
          <SourceNote
            n={data.total_connections}
            source={
              data.generated_with?.startsWith('POST')
                ? 'stored optimizer run (live compute)'
                : 'docs/equity-report.json (GET /api/equity/report)'
            }
            period={`${data.period} · ${data.volume_mode}`}
          />

          <div className="grid grid-cols-1 gap-3 xl:grid-cols-2">
            <div className="rounded-xl border border-border bg-card">
              <div className="flex items-center gap-2 border-b border-border px-3 py-2">
                <TrendingUp className="h-4 w-4 text-optimized" />
                <h3 className="text-xs font-bold text-text-primary">Biggest winners</h3>
              </div>
              <div className="overflow-x-auto"><table className="w-full">
                <thead>
                  <tr className="text-left text-[10px] uppercase tracking-wide text-text-muted">
                    <th className="px-2 py-1">Stop</th>
                    <th className="px-2 py-1">Routes</th>
                    <th className="px-2 py-1 text-right">Avg change</th>
                    <th className="px-2 py-1 text-right">Worse-off conns</th>
                    <th className="px-2 py-1 text-right">Riders</th>
                  </tr>
                </thead>
                <tbody>{stopRows(data.winners ?? [])}</tbody>
              </table></div>
            </div>

            <div className="rounded-xl border border-border bg-card">
              <div className="flex items-center gap-2 border-b border-border px-3 py-2">
                <TrendingDown className="h-4 w-4 text-danger" />
                <h3 className="text-xs font-bold text-text-primary">Worse-off stops</h3>
              </div>
              <div className="overflow-x-auto"><table className="w-full">
                <thead>
                  <tr className="text-left text-[10px] uppercase tracking-wide text-text-muted">
                    <th className="px-2 py-1">Stop</th>
                    <th className="px-2 py-1">Routes</th>
                    <th className="px-2 py-1 text-right">Avg change</th>
                    <th className="px-2 py-1 text-right">Worse-off conns</th>
                    <th className="px-2 py-1 text-right">Riders</th>
                  </tr>
                </thead>
                <tbody>{stopRows(data.losers ?? [])}</tbody>
              </table></div>
            </div>
          </div>

          {data.wards?.rows && data.wards.rows.length > 0 && (
            <div className="rounded-xl border border-border bg-card">
              <div className="border-b border-border px-3 py-2">
                <h3 className="text-xs font-bold text-text-primary">By ward</h3>
                <p className="mt-0.5 text-[10px] text-text-muted">
                  Average wait change per transfer stop, summed rider proxy.
                  {data.wards.stops_unassigned > 0 &&
                    ` ${data.wards.stops_unassigned} stops unmatched to a ward (excluded).`}
                </p>
              </div>
              <div className="overflow-x-auto"><table className="w-full">
                <thead>
                  <tr className="text-left text-[10px] uppercase tracking-wide text-text-muted">
                    <th className="px-2 py-1">Ward</th>
                    <th className="px-2 py-1 text-right">Stops</th>
                    <th className="px-2 py-1 text-right">Avg change</th>
                    <th className="px-2 py-1 text-right">Worse-off stops</th>
                    <th className="px-2 py-1 text-right">Riders (proxy)</th>
                    <th
                      className="px-2 py-1 text-right"
                      title="TTS 2022 resident transit trips per day in this ward (Transportation Tomorrow Survey)">
                      Transit demand
                    </th>
                    <th
                      className="px-2 py-1 text-right"
                      title="Share of the ward's transit trips that use 2+ routes — the transfer-making demand this tool optimizes">
                      Transfer share
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {data.wards.rows.map((w) => (
                    <tr key={w.ward} className="border-b border-border/60 hover:bg-card-hover">
                      <td className="px-2 py-1.5 text-xs font-semibold text-text-primary">
                        Ward {w.ward}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs text-text-secondary">{w.stops}</td>
                      <td
                        className={`px-2 py-1.5 text-right text-xs font-bold ${
                          w.delta_minutes < 0 ? 'text-optimized' : 'text-danger'
                        }`}
                      >
                        {fmt(w.delta_minutes)}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs text-text-secondary">
                        {w.worse_off_stops}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs text-text-muted">
                        {fmtInt(w.riders_at_stops_proxy)}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs text-text-muted">
                        {typeof w.tts_transit_trips_24h === 'number'
                          ? fmtInt(w.tts_transit_trips_24h)
                          : '—'}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs text-text-muted">
                        {typeof w.tts_transfer_share_pct === 'number'
                          ? `${w.tts_transfer_share_pct}%`
                          : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table></div>
            </div>
          )}

          {wardDemo?.available && wardDemo.wards && (
            <div className="mt-3 rounded-xl border border-border bg-card">
              <div className="border-b border-border px-3 py-2">
                <h3 className="text-xs font-bold text-text-primary">Ward demographics (2021 Census)</h3>
                <p className="mt-0.5 text-[10px] text-text-muted">
                  {wardDemo.source} — population near affected stops
                </p>
              </div>
              <div className="overflow-x-auto"><table className="w-full">
                <thead>
                  <tr className="text-left text-[10px] uppercase tracking-wide text-text-muted">
                    <th className="px-2 py-1">Ward</th>
                    <th className="px-2 py-1 text-right">Population</th>
                    <th className="px-2 py-1 text-right">Med. income</th>
                    <th className="px-2 py-1 text-right">Transit use</th>
                    <th className="px-2 py-1 text-right">Low income</th>
                  </tr>
                </thead>
                <tbody>
                  {wardDemo.wards.map((w) => (
                    <tr key={w.ward} className="border-b border-border/60 hover:bg-card-hover">
                      <td className="px-2 py-1.5 text-xs font-semibold text-text-primary">
                        Ward {w.ward}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs tabular-nums text-text-secondary">
                        {w.population.toLocaleString()}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs tabular-nums text-text-secondary">
                        ${w.median_income_individual_2020.toLocaleString()}
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs tabular-nums">
                        <span className={w.transit_mode_share_pct >= 15 ? 'font-bold text-bottleneck' : 'text-text-secondary'}>
                          {w.transit_mode_share_pct}%
                        </span>
                      </td>
                      <td className="px-2 py-1.5 text-right text-xs tabular-nums">
                        <span className={w.low_income_LIMAT_pct >= 13 ? 'font-bold text-bottleneck' : 'text-text-secondary'}>
                          {w.low_income_LIMAT_pct}%
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table></div>
              {wardDemo.note && (
                <p className="px-2 py-1.5 text-[9px] text-text-muted">{wardDemo.note}</p>
              )}
            </div>
          )}

          <p className="px-1 text-[10px] leading-relaxed text-text-muted">
            Every wait-minute saved is concentrated at specific stops; the stops that lose are the
            other side of the same coin — a route shifted to serve one transfer can lengthen waits
            at another. Riders-at-stop is the real APC boarding proxy; where it shows 0, boarding
            data is missing and the stop should be ground-truthed before weighing it. Regenerate the
            report from the backend with{' '}
            <code className="rounded bg-card-hover px-1 py-0.5">
              scripts/equity_report.py --ward-csv app/data/ward_stops.csv
            </code>
            {' '}— or ask whoever runs the tool.
          
          </p>
        </div>
      )}
    </div>
  );
}
